typedef void (*EventCallback)(int event_id, void* data);

// Callback function matching the signature
void log_event(int id, void* data) {
    /* Event processing logic */
}

// System function accepting the callback
void EventSystem_Register(EventCallback handler) {
    // Store handler internally
}

void EventSystem_Trigger(int id, void* payload, EventCallback current_cb) {
    current_cb(id, payload); // Indirect function call
}

// Usage: Pass function name (address)
EventSystem_Register(log_event);

// Direct call example
EventCallback fp = log_event;
fp(101, NULL);
// Or: (*fp)(101, NULL);
